-- SweetCommerce standard-ordering baseline for PostgreSQL 16.
-- UUIDs are generated by the application. Financial values are integer MYR sen.
CREATE TABLE account (
  id uuid PRIMARY KEY,
  role text NOT NULL CHECK (role IN ('CUSTOMER','ADMIN')),
  phone_e164 text,
  recovery_email text,
  status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')),
  credential_epoch bigint NOT NULL DEFAULT 1 CHECK (credential_epoch >= 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (role <> 'CUSTOMER' OR phone_e164 IS NOT NULL),
  CHECK (phone_e164 IS NOT NULL OR recovery_email IS NOT NULL)
);
CREATE UNIQUE INDEX account_customer_phone ON account(phone_e164) WHERE role = 'CUSTOMER';
CREATE UNIQUE INDEX account_single_admin ON account(role) WHERE role = 'ADMIN';

CREATE TABLE otp_challenge (
  id uuid PRIMARY KEY, role text NOT NULL CHECK (role IN ('CUSTOMER','ADMIN')),
  purpose text NOT NULL DEFAULT 'SIGN_IN' CHECK (purpose IN ('SIGN_IN','RECOVERY')),
  enrollment_epoch bigint CHECK (enrollment_epoch >= 1),
  destination_fingerprint bytea NOT NULL, verifier bytea NOT NULL,
  customer_destination_cipher bytea,
  created_at timestamptz NOT NULL, expires_at timestamptz NOT NULL,
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), used_at timestamptz,
  CHECK (expires_at > created_at), CHECK (purpose <> 'RECOVERY' OR role = 'ADMIN'),
  CHECK ((role = 'ADMIN') = (enrollment_epoch IS NOT NULL)),
  CHECK (role <> 'CUSTOMER' OR used_at IS NOT NULL OR customer_destination_cipher IS NOT NULL)
);
CREATE INDEX otp_by_destination ON otp_challenge(role, destination_fingerprint, created_at DESC);
CREATE TABLE session (
  token_hash bytea PRIMARY KEY, account_id uuid NOT NULL REFERENCES account(id),
  csrf_hash bytea NOT NULL, created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL, revoked_at timestamptz,
  CHECK (expires_at > created_at)
);
CREATE INDEX session_account ON session(account_id, expires_at);

CREATE TABLE product (
  id uuid PRIMARY KEY, name text NOT NULL, category text CHECK (length(category) BETWEEN 1 AND 80),
  status text NOT NULL CHECK (status IN ('DRAFT','LISTED','UNLISTED','SUSPENDED','SOLD_OUT','ARCHIVED')),
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1)
);
CREATE INDEX product_listing ON product(status, id);
CREATE INDEX product_category_listing ON product(status, category, id);
CREATE TABLE product_media (
  id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product(id),
  object_key text NOT NULL UNIQUE, content_digest bytea NOT NULL,
  byte_count integer NOT NULL CHECK (byte_count BETWEEN 1 AND 5242880),
  media_type text NOT NULL CHECK (media_type IN ('image/jpeg','image/png','image/webp')),
  lifecycle text NOT NULL CHECK (lifecycle IN ('STAGED','ATTACHED','RETIRED')),
  created_at timestamptz NOT NULL, retired_at timestamptz,
  UNIQUE (product_id, id),
  CHECK ((lifecycle = 'RETIRED') = (retired_at IS NOT NULL))
);
CREATE INDEX product_media_cleanup ON product_media(lifecycle, created_at);
CREATE TABLE product_gallery (
  product_id uuid NOT NULL REFERENCES product(id),
  ordinal integer NOT NULL CHECK (ordinal BETWEEN 1 AND 12),
  media_id uuid NOT NULL UNIQUE,
  PRIMARY KEY (product_id, ordinal),
  FOREIGN KEY (product_id, media_id) REFERENCES product_media(product_id, id)
);
CREATE TABLE variant (
  id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product(id),
  name text NOT NULL, flavour text NOT NULL, available boolean NOT NULL,
  unit_minor bigint NOT NULL CHECK (unit_minor >= 0),
  prep_minutes integer NOT NULL CHECK (prep_minutes BETWEEN 0 AND 10080)
);
CREATE INDEX variant_product ON variant(product_id, id);
CREATE TABLE cart (
  account_id uuid PRIMARY KEY REFERENCES account(id),
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE cart_line (
  id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES cart(account_id),
  variant_id uuid NOT NULL REFERENCES variant(id),
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 999),
  UNIQUE (account_id, variant_id)
);
CREATE TABLE checkout_review (
  id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES account(id),
  cart_version bigint NOT NULL CHECK (cart_version >= 1),
  review_digest bytea NOT NULL, terms_version text NOT NULL,
  review_snapshot jsonb NOT NULL,
  expires_at timestamptz NOT NULL, consumed_at timestamptz,
  status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','SUBMITTED','ABANDONED','EXPIRED')),
  updated_at timestamptz NOT NULL,
  CHECK ((status = 'SUBMITTED') = (consumed_at IS NOT NULL))
);
CREATE INDEX review_expiry ON checkout_review(expires_at);
CREATE TABLE operating_policy (
  singleton boolean PRIMARY KEY DEFAULT TRUE CHECK (singleton),
  open_weekdays smallint[] NOT NULL CHECK (
    cardinality(open_weekdays) BETWEEN 1 AND 7
    AND open_weekdays <@ ARRAY[1,2,3,4,5,6,7]::smallint[]
    AND array_position(open_weekdays, NULL) IS NULL),
  opens_at time NOT NULL, closes_at time NOT NULL CHECK (closes_at > opens_at),
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1)
);
CREATE TABLE capacity_day (
  service_date date PRIMARY KEY, closed boolean NOT NULL,
  max_units integer NOT NULL CHECK (max_units >= 0),
  allocated_units integer NOT NULL DEFAULT 0 CHECK (allocated_units >= 0),
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1),
  CHECK (allocated_units <= max_units)
);
CREATE TABLE capacity_product_limit (
  service_date date NOT NULL REFERENCES capacity_day(service_date),
  product_id uuid NOT NULL REFERENCES product(id),
  max_units integer NOT NULL CHECK (max_units >= 0),
  PRIMARY KEY (service_date, product_id)
);

CREATE TABLE standard_order (
  id uuid PRIMARY KEY, order_number text NOT NULL UNIQUE,
  account_id uuid NOT NULL REFERENCES account(id),
  checkout_review_id uuid NOT NULL UNIQUE REFERENCES checkout_review(id),
  status text NOT NULL CHECK (status IN ('AWAITING_FEE','AWAITING_CASH','PENDING_PROOF','PAYMENT_REVIEW','EXCEPTION','ACCEPTED','PREPARING','READY','HANDED_OFF','COMPLETED','EXPIRED','CANCELLED','REJECTED','NO_SHOW')),
  fulfilment text NOT NULL CHECK (fulfilment IN ('PICKUP','MERCHANT_LALAMOVE','CUSTOMER_LALAMOVE')),
  payment_method text NOT NULL CHECK (payment_method IN ('DUITNOW','CASH')),
  service_date date NOT NULL, requested_handoff_at timestamptz NOT NULL, promised_handoff_at timestamptz,
  ready_at timestamptz, driver_arrived_at timestamptz, handoff_at timestamptz,
  fulfilment_snapshot jsonb NOT NULL,
  subtotal_minor bigint NOT NULL CHECK (subtotal_minor >= 0),
  fee_minor bigint CHECK (fee_minor >= 0),
  total_minor bigint GENERATED ALWAYS AS (subtotal_minor + fee_minor) STORED,
  fee_version bigint CHECK (fee_version >= 1), fee_confirmed_at timestamptz,
  terms_version text NOT NULL, proof_due_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1),
  accepted_at timestamptz, created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CHECK (payment_method <> 'CASH' OR fulfilment = 'PICKUP'),
  CHECK (driver_arrived_at IS NULL OR fulfilment <> 'PICKUP'),
  CHECK (fulfilment = 'MERCHANT_LALAMOVE' OR (fee_minor IS NOT NULL AND fee_minor = 0))
);
CREATE INDEX standard_owner_list ON standard_order(account_id, created_at DESC, id DESC);
CREATE INDEX standard_merchant_work ON standard_order(status, updated_at, id);
CREATE INDEX standard_expiry ON standard_order(proof_due_at, id) WHERE status = 'PENDING_PROOF';
CREATE INDEX standard_prep_day ON standard_order(service_date, status);
CREATE TABLE delivery_fee_offer (
  order_id uuid NOT NULL REFERENCES standard_order(id),
  revision bigint NOT NULL CHECK (revision >= 1), serviceable boolean NOT NULL,
  offered_handoff_at timestamptz, fee_minor bigint CHECK (fee_minor >= 0),
  terms_version text NOT NULL, terms_snapshot jsonb NOT NULL,
  reason text NOT NULL, created_at timestamptz NOT NULL,
  PRIMARY KEY (order_id, revision),
  CHECK (NOT serviceable OR (offered_handoff_at IS NOT NULL AND fee_minor IS NOT NULL))
);
CREATE TABLE order_recovery_agreement (
  id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES standard_order(id),
  order_version bigint NOT NULL CHECK (order_version >= 1),
  kind text NOT NULL CHECK (kind IN ('RESCHEDULE','REDELIVERY','DELIVERY_ADJUSTMENT')),
  proposed_handoff_at timestamptz, new_production boolean,
  extra_minor bigint CHECK (extra_minor > 0),
  agreed_at timestamptz NOT NULL,
  consent_channel text NOT NULL CHECK (consent_channel IN ('PHONE','WHATSAPP','IN_PERSON')),
  consent_reference text NOT NULL, reason text NOT NULL,
  recorded_by uuid NOT NULL REFERENCES account(id), recorded_at timestamptz NOT NULL,
  CHECK ((kind IN ('RESCHEDULE','REDELIVERY') AND proposed_handoff_at IS NOT NULL AND new_production IS NOT NULL AND extra_minor IS NULL)
      OR (kind = 'DELIVERY_ADJUSTMENT' AND proposed_handoff_at IS NULL AND new_production IS NULL AND extra_minor IS NOT NULL))
);
CREATE INDEX recovery_order ON order_recovery_agreement(order_id, recorded_at);
CREATE TABLE standard_order_line (
  order_id uuid NOT NULL REFERENCES standard_order(id),
  variant_id uuid NOT NULL REFERENCES variant(id),
  product_id uuid NOT NULL REFERENCES product(id),
  cart_line_generation uuid,
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 999),
  unit_minor bigint NOT NULL CHECK (unit_minor >= 0),
  display_snapshot jsonb NOT NULL,
  PRIMARY KEY (order_id, variant_id)
);
CREATE TABLE capacity_allocation (
  order_id uuid NOT NULL REFERENCES standard_order(id),
  service_date date NOT NULL REFERENCES capacity_day(service_date),
  product_id uuid NOT NULL REFERENCES product(id),
  quantity integer NOT NULL CHECK (quantity > 0),
  state text NOT NULL CHECK (state IN ('HELD','COMMITTED','USED','RELEASED')),
  generation integer NOT NULL CHECK (generation > 0),
  PRIMARY KEY (order_id, service_date, product_id, generation)
);
CREATE UNIQUE INDEX allocation_one_live_generation ON capacity_allocation(order_id, service_date, product_id)
  WHERE state IN ('HELD','COMMITTED');
CREATE INDEX allocation_product_day ON capacity_allocation(service_date, product_id) INCLUDE (quantity)
  WHERE state IN ('HELD','COMMITTED','USED');

CREATE TABLE charge (
  id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES standard_order(id),
  category text NOT NULL CHECK (category IN ('STANDARD','STANDARD_ADJUSTMENT')),
  state text NOT NULL CHECK (state IN ('OPEN','PROOF_REVIEW','PAID','DISPUTED','EXPIRED','CANCELLED','PARTIALLY_REFUNDED','REFUNDED')),
  expected_minor bigint NOT NULL CHECK (expected_minor >= 0),
  due_at timestamptz, created_at timestamptz NOT NULL,
  top_up_requested_at timestamptz, top_up_due_at timestamptz,
  top_up_outstanding_minor bigint CHECK (top_up_outstanding_minor > 0),
  recovery_agreement_id uuid UNIQUE REFERENCES order_recovery_agreement(id),
  version bigint NOT NULL DEFAULT 1 CHECK (version >= 1),
  CHECK ((category = 'STANDARD_ADJUSTMENT') = (recovery_agreement_id IS NOT NULL)),
  CHECK (num_nonnulls(top_up_requested_at, top_up_due_at, top_up_outstanding_minor) = 0 OR
    (num_nonnulls(top_up_requested_at, top_up_due_at, top_up_outstanding_minor) = 3 AND category = 'STANDARD' AND
     top_up_due_at = top_up_requested_at + interval '30 minutes'))
);
CREATE UNIQUE INDEX charge_one_standard ON charge(order_id) WHERE category = 'STANDARD';
CREATE INDEX charge_order ON charge(order_id, created_at, id);
CREATE INDEX charge_due ON charge(due_at, id) WHERE state IN ('OPEN','PROOF_REVIEW');
CREATE TABLE payment_proof (
  id uuid PRIMARY KEY, charge_id uuid NOT NULL REFERENCES charge(id),
  object_key text NOT NULL UNIQUE, content_digest bytea NOT NULL,
  byte_count integer NOT NULL CHECK (byte_count BETWEEN 1 AND 5242880),
  media_type text NOT NULL CHECK (media_type IN ('image/jpeg','image/png','application/pdf')),
  state text NOT NULL CHECK (state IN ('REVIEW','ACCEPTED','REJECTED')),
  review_disposition text NOT NULL CHECK (review_disposition IN ('TIMELY','RECONCILIATION_ONLY')),
  received_at timestamptz NOT NULL, reviewed_at timestamptz, reviewed_by uuid REFERENCES account(id),
  UNIQUE (charge_id, content_digest)
);
CREATE INDEX proof_review ON payment_proof(state, received_at, id);
CREATE TABLE settlement_case (
  id uuid PRIMARY KEY, charge_id uuid NOT NULL REFERENCES charge(id),
  proof_id uuid REFERENCES payment_proof(id),
  kind text NOT NULL CHECK (kind IN ('LATE_PROOF','AMOUNT_MISMATCH','TRANSFER_UNMATCHED','STANDARD_FULFILMENT_INFEASIBLE')),
  status text NOT NULL CHECK (status IN ('OPEN','RESOLVED')),
  notes text, opened_at timestamptz NOT NULL, resolved_at timestamptz,
  resolved_by uuid REFERENCES account(id),
  CHECK ((status = 'RESOLVED') = (num_nonnulls(resolved_at,resolved_by) = 2))
);
CREATE INDEX settlement_case_queue ON settlement_case(status, opened_at, id);
CREATE TABLE money_entry (
  id uuid PRIMARY KEY, charge_id uuid NOT NULL REFERENCES charge(id),
  kind text NOT NULL CHECK (kind IN ('RECEIPT','REFUND')),
  rail text NOT NULL CHECK (rail IN ('DUITNOW','CASH')),
  external_reference text NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor > 0),
  occurred_at timestamptz NOT NULL, actor_id uuid NOT NULL REFERENCES account(id),
  reason text, settlement_case_id uuid REFERENCES settlement_case(id),
  recorded_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (rail, kind, external_reference)
);
CREATE INDEX money_charge ON money_entry(charge_id, kind);

-- Refund commands lock the parent and charge before taking this receipt lock.
-- PostgreSQL would otherwise require an UPDATE grant for SELECT FOR UPDATE.
CREATE FUNCTION sweetcommerce.lock_receipt(parent_charge uuid, target_receipt uuid)
RETURNS uuid
LANGUAGE sql SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  SELECT id FROM sweetcommerce.money_entry
  WHERE charge_id = parent_charge AND id = target_receipt AND kind = 'RECEIPT'
  FOR UPDATE
$$;
REVOKE ALL ON FUNCTION sweetcommerce.lock_receipt(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sweetcommerce.lock_receipt(uuid, uuid) TO sweetcommerce_api;

CREATE TABLE full_refund_obligation (
  receipt_id uuid PRIMARY KEY REFERENCES money_entry(id),
  amount_minor bigint NOT NULL CHECK (amount_minor > 0),
  reason text NOT NULL CHECK (reason = 'MERCHANT_UNABLE'),
  recorded_at timestamptz NOT NULL, actor_id uuid NOT NULL REFERENCES account(id)
);
CREATE TABLE refund_intent (
  id uuid PRIMARY KEY, receipt_id uuid NOT NULL REFERENCES money_entry(id),
  amount_minor bigint NOT NULL CHECK (amount_minor > 0),
  status text NOT NULL CHECK (status IN ('RESERVED','UNCERTAIN','POSTED','VOIDED')),
  requested_by uuid NOT NULL REFERENCES account(id), reason text NOT NULL,
  created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL,
  disposition_reason text, refund_entry_id uuid UNIQUE REFERENCES money_entry(id),
  CHECK ((status = 'POSTED') = (refund_entry_id IS NOT NULL))
);
CREATE INDEX refund_receipt_status ON refund_intent(receipt_id, status);

CREATE TABLE command_receipt (
  actor_id uuid NOT NULL REFERENCES account(id), operation text NOT NULL,
  idem_key uuid NOT NULL, request_digest bytea NOT NULL,
  result_reference jsonb NOT NULL, created_at timestamptz NOT NULL,
  PRIMARY KEY (actor_id, operation, idem_key)
);
CREATE TABLE audit_event (
  id uuid PRIMARY KEY, actor_id uuid REFERENCES account(id),
  feature text NOT NULL, resource_id uuid NOT NULL, action text NOT NULL,
  occurred_at timestamptz NOT NULL, reason_code text, request_id text NOT NULL,
  safe_change jsonb NOT NULL DEFAULT '{}'
);
CREATE INDEX audit_resource ON audit_event(resource_id, occurred_at DESC, id DESC);
CREATE TABLE durable_work (
  id uuid PRIMARY KEY, event_key text NOT NULL UNIQUE,
  kind text NOT NULL CHECK (kind IN ('NOTICE','STANDARD_PROOF_EXPIRY','STANDARD_TOP_UP_EXPIRY')),
  resource_id uuid NOT NULL, work_state text NOT NULL CHECK (work_state IN ('READY','LEASED','SUCCEEDED','DEAD')),
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  not_before timestamptz NOT NULL, lease_until timestamptz, lease_token uuid,
  payload_version integer NOT NULL DEFAULT 1 CHECK (payload_version >= 1),
  payload jsonb NOT NULL DEFAULT '{}',
  last_safe_error text, created_at timestamptz NOT NULL
);
CREATE INDEX work_dispatch ON durable_work(not_before, id) WHERE work_state = 'READY';
CREATE INDEX work_reclaim ON durable_work(lease_until, id) WHERE work_state = 'LEASED';
CREATE TABLE notice_attempt (
  work_id uuid NOT NULL REFERENCES durable_work(id), attempt_no integer NOT NULL CHECK (attempt_no BETWEEN 1 AND 4),
  attempted_at timestamptz NOT NULL, channel text NOT NULL,
  outcome text NOT NULL CHECK (outcome IN ('DELIVERED','FAILED','UNKNOWN')),
  safe_reason text, PRIMARY KEY (work_id, attempt_no)
);
CREATE TABLE notice_followup (
  work_id uuid PRIMARY KEY REFERENCES durable_work(id),
  disposition text NOT NULL CHECK (disposition IN ('MANUAL_CONTACT','PROVIDER_RECONCILED')),
  reason text NOT NULL, resolved_by uuid NOT NULL REFERENCES account(id), resolved_at timestamptz NOT NULL
);

-- Grant access per workflow. Tables created by later migrations get no runtime grants by default.
GRANT USAGE ON SCHEMA sweetcommerce TO sweetcommerce_api, sweetcommerce_worker;

GRANT SELECT, INSERT, UPDATE ON product, product_media, variant,
  cart, cart_line, checkout_review, operating_policy, capacity_day, capacity_product_limit,
  standard_order, capacity_allocation, charge, settlement_case, refund_intent
  TO sweetcommerce_api;
GRANT SELECT, INSERT ON account, otp_challenge, session, payment_proof TO sweetcommerce_api;
GRANT UPDATE (status, credential_epoch, phone_e164, recovery_email) ON account TO sweetcommerce_api;
GRANT UPDATE (attempts, used_at, customer_destination_cipher) ON otp_challenge TO sweetcommerce_api;
GRANT UPDATE (revoked_at) ON session TO sweetcommerce_api;
GRANT UPDATE (state, reviewed_at, reviewed_by) ON payment_proof TO sweetcommerce_api;
GRANT DELETE ON otp_challenge, cart_line, capacity_product_limit TO sweetcommerce_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON product_gallery TO sweetcommerce_api;

-- Runtime can append facts and evidence but cannot rewrite, delete or truncate them.
GRANT SELECT, INSERT ON delivery_fee_offer, order_recovery_agreement, standard_order_line,
  money_entry, full_refund_obligation, command_receipt, audit_event, durable_work, notice_followup
  TO sweetcommerce_api;
GRANT SELECT ON notice_attempt TO sweetcommerce_api;

GRANT SELECT ON durable_work, notice_attempt TO sweetcommerce_worker;
GRANT UPDATE (work_state, attempt_count, not_before, lease_until, lease_token, last_safe_error)
  ON durable_work TO sweetcommerce_worker;
GRANT INSERT ON notice_attempt TO sweetcommerce_worker;
GRANT INSERT (id, feature, resource_id, action, occurred_at, reason_code, request_id, safe_change)
  ON audit_event TO sweetcommerce_worker;

-- Expiry can lock and release commitments without reading private snapshots or proof objects.
GRANT SELECT (id, status, service_date, proof_due_at, version, updated_at),
  UPDATE (status, version, updated_at) ON standard_order TO sweetcommerce_worker;
GRANT SELECT (id, order_id, category, state, due_at, top_up_requested_at, top_up_due_at, version),
  UPDATE (state, version) ON charge TO sweetcommerce_worker;
GRANT SELECT (id, charge_id, state, review_disposition, received_at)
  ON payment_proof TO sweetcommerce_worker;
GRANT SELECT ON capacity_day, capacity_allocation TO sweetcommerce_worker;
GRANT UPDATE (allocated_units, version) ON capacity_day TO sweetcommerce_worker;
GRANT UPDATE (state) ON capacity_allocation TO sweetcommerce_worker;
